<template><div class="checkout-wrap history-page"><button class="text-button" @click="$router.push({path:'/guest',query:{storeId}})">← 返回菜单</button><h1>订单历史</h1><p class="history-subtitle">仅显示此设备提交的订单</p><div v-if="orders.length" class="history-total-card"><div><span>累计有效订单金额</span><small>{{orders.length}} 笔订单（不含已取消）</small></div><strong>¥{{historyTotal.toLocaleString()}}</strong></div><el-empty v-if="!loading&&!orders.length" description="还没有订单记录"/><div v-for="order in orders" :key="order.id" class="history-order"><div class="history-order-head"><div><b>{{order.id}}</b><small>桌号 {{order.tableNo}} · {{new Date(order.createdAt).toLocaleString()}}</small></div><el-tag :type="statusType(order.status)">{{statusLabel(order.status)}}</el-tag></div><div v-for="item in order.items" :key="item.productId" class="checkout-item"><span>{{item.name}} × {{item.quantity}}</span><b>¥{{item.subtotal.toLocaleString()}}</b></div><div class="checkout-total"><span>合计</span><b>¥{{order.total.toLocaleString()}}</b></div></div></div></template>
<script setup lang="ts">import {ref,onMounted,computed} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api,type Order} from '../api';import {activeStoreId} from '../storeContext';const route=useRoute(),router=useRouter(),storeId=String(route.query.storeId||activeStoreId.value),orders=ref<Order[]>([]),loading=ref(true),historyTotal=computed(()=>orders.value.filter(o=>o.status!=='cancelled').reduce((sum,o)=>sum+o.total,0));function statusLabel(status:string){return({new:'新订单',preparing:'制作中',completed:'已完成',cancelled:'已取消'} as Record<string,string>)[status]||status}function statusType(status:string){return status==='new'?'danger':status==='completed'?'success':status==='cancelled'?'info':'warning'}onMounted(async()=>{try{const entries=JSON.parse(localStorage.getItem(`guest-orders:${storeId}`)||'[]') as Array<{id:string;token:string}>;const rows=await Promise.all(entries.filter(x=>x&&x.id&&x.token).map(x=>api.get(`/guest/orders/${x.id}`,{headers:{'X-Order-Access-Token':x.token}}).then(r=>r.data.data as Order).catch(()=>undefined)));orders.value=rows.filter((o):o is Order=>o!==undefined&&o.storeId===storeId)}finally{loading.value=false}});</script>


